function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y);}
function entityCenter(e){if(e.type==='base')return{x:e.x+TILE,y:e.y+TILE};if(e.type==='tower'||e.type==='wall'||e.type==='house'||e.type==='harbor'||e.type==='apartment'||e.type==='training'||e.type==='silo'||e.type==='radar')return{x:e.x+TILE/2,y:e.y+TILE/2};return{x:e.x,y:e.y};}
