refreshUnitConfigUI();(function initUnitFloatingTooltip(){const sidebar=document.getElementById('sidebar');if(!sidebar)return;let tip=document.getElementById('unit-floating-tip');if(!tip){tip=document.createElement('div');tip.id='unit-floating-tip';document.body.appendChild(tip);}
const placeTip=(clientX,clientY)=>{const rect=tip.getBoundingClientRect();const pad=12;let x=clientX-rect.width-pad;if(x<4)x=clientX+pad;let y=clientY-18;if(y+rect.height>window.innerHeight-4)y=window.innerHeight-rect.height-4;if(y<4)y=4;tip.style.left=x+'px';tip.style.top=y+'px';};const showTip=(btn,clientX,clientY)=>{if(!btn||!btn.dataset.tip)return;tip.textContent=btn.dataset.tip;tip.classList.add('show');placeTip(clientX,clientY);};const hideTip=()=>tip.classList.remove('show');sidebar.addEventListener('mousemove',(e)=>{const btn=e.target.closest('.unit-btn[data-tip]');if(!btn){hideTip();return;}
showTip(btn,e.clientX,e.clientY);});sidebar.addEventListener('mouseleave',hideTip);sidebar.addEventListener('mouseover',(e)=>{const btn=e.target.closest('.unit-btn[data-tip]');if(!btn)return;const r=btn.getBoundingClientRect();showTip(btn,r.left+r.width*0.5,r.top+r.height*0.5);});sidebar.addEventListener('mouseout',(e)=>{if(e.relatedTarget&&e.relatedTarget.closest&&e.relatedTarget.closest('.unit-btn[data-tip]'))return;hideTip();});})();function formatProductionInfo(queue){if(!queue||!queue.length)return'';const pct=Math.floor(queue[0].timer/queue[0].maxTimer*100);return queue.length===1?`⏳ ${pct}%`:`⏳ ${pct}% | +${queue.length - 1}`;}
function isBuildAreaFree(tx,ty,tw,th){for(let dy=0;dy<th;dy++){for(let dx=0;dx<tw;dx++){let cx=tx+dx,cy=ty+dy;if(cx<0||cy<0||cx>=MAP_W||cy>=MAP_H)return false;let t=map[cy][cx];if(t!==0&&t!==5&&t!==6&&t!==7)return false;}}
for(let faction of[player,ai]){for(let b of[...faction.bases,...faction.towers,...faction.houses,...(faction.apartments||[]),...(faction.trainings||[]),...faction.walls,...faction.harbors,...(faction.silos||[]),...(faction.radars||[])]){let bw=b.type==='base'?2:1;let bh=b.type==='base'?2:1;let btx=Math.round(b.x/TILE),bty=Math.round(b.y/TILE);if(tx<btx+bw&&tx+tw>btx&&ty<bty+bh&&ty+th>bty)return false;}}
return true;}
